const profileSource=r'''use std::{error::Error, fs, io};
use revault_page_api::{allocation_chunk_bytes, weakened_allocation_allowed, Error as ApiError, SecureVec};
const LIMIT:u64=8*1024*1024;
fn status(key:&str)->Result<u64,Box<dyn Error>>{let s=fs::read_to_string("/proc/self/status")?;let l=s.lines().find(|x|x.starts_with(&format!("{key}:"))).ok_or_else(||io::Error::other(format!("missing {key}")))?;Ok(l.split_whitespace().nth(1).ok_or_else(||io::Error::other("missing status value"))?.parse()?)}
fn limits()->Result<(u64,u64),Box<dyn Error>>{let s=fs::read_to_string("/proc/self/limits")?;let f=s.lines().find(|x|x.starts_with("Max locked memory")).ok_or_else(||io::Error::other("missing memlock limit"))?.split_whitespace().collect::<Vec<_>>();if f.len()!=6||f[5]!="bytes"{return Err(io::Error::other("unexpected memlock limit format").into())}Ok((f[3].parse()?,f[4].parse()?))}
fn row(variant:&str,pass:usize,index:usize,size:usize,stage:&str)->Result<u64,Box<dyn Error>>{let locked=status("VmLck")?.checked_mul(1024).ok_or_else(||io::Error::other("VmLck overflow"))?;let rss=status("VmRSS")?;let(soft,hard)=limits()?;if soft!=LIMIT||hard!=LIMIT{return Err(io::Error::other(format!("memlock changed {soft}/{hard}")).into())}if locked>LIMIT{return Err(io::Error::other(format!("VmLck exceeds limit: {locked}")).into())}if stage=="baseline"&&locked!=0{return Err(io::Error::other(format!("baseline VmLck {locked} != 0")).into())}println!("{{\"variant\":\"{variant}\",\"pass\":{pass},\"index\":{index},\"stage\":\"{stage}\",\"requested_bytes\":{size},\"capacity_bytes_source_inferred\":{size},\"VmLck_bytes\":{locked},\"VmRSS_kib\":{rss},\"memlock_soft_bytes\":{soft},\"memlock_hard_bytes\":{hard},\"weak_policy\":false}}");Ok(locked)}
fn run(variant:&str)->Result<(),Box<dyn Error>>{if weakened_allocation_allowed(){return Err(io::Error::other("weak allocation policy must remain false").into())}if allocation_chunk_bytes()!=65536{return Err(io::Error::other(format!("allocation_chunk_bytes {} != 65536",allocation_chunk_bytes())).into())}if std::env::var("PROFILE_HOST_PAGE_SIZE").ok().as_deref()!=Some("4096"){return Err(io::Error::other("host page size not verified as 4096").into())}row(variant,0,0,0,"baseline")?;let mut count=0usize;for pass in 1..=2{for index in 0..64{let size=8192+index*4096;row(variant,pass,index,size,"before")?;let byte=(((index+(pass-1)*64)%255)+1)as u8;let input=vec![byte;size];let value=match SecureVec::try_from_slice(&input){Ok(v)=>v,Err(e)if variant=="old"&&e==ApiError::WeakAllocationDisabled=>{let locked=row(variant,pass,index,size,"expected_old_refusal")?;println!("{{\"variant\":\"old\",\"outcome\":\"expected_refusal_not_ignored\",\"pass\":{pass},\"index\":{index},\"requested_bytes\":{size},\"VmLck_bytes\":{locked},\"error\":\"WeakAllocationDisabled\"}}");return Ok(())},Err(e)=>return Err(e.into())};if value.len()!=size{return Err(io::Error::other("SecureVec length mismatch").into())}let matched=value.with_bytes(|bytes|bytes==input.as_slice())?;if !matched{return Err(io::Error::other("exact scoped byte comparison failed").into())}row(variant,pass,index,size,"live")?;drop(value);row(variant,pass,index,size,"after_drop")?;count+=1}}if variant=="old"{return Err(io::Error::other("old variant did not refuse under pressure").into())}if count!=128{return Err(io::Error::other(format!("new completed {count}, expected 128")).into())}println!("{{\"variant\":\"new\",\"outcome\":\"completed\",\"allocations\":{count},\"passes\":2}}");Ok(())}
fn main(){let variant=std::env::args().nth(1).unwrap_or_default();if variant!="old"&&variant!="new"{eprintln!("variant must be old or new");std::process::exit(2)}if let Err(e)=run(&variant){eprintln!("profile failure: {e}");std::process::exit(1)}}
''';
void require(bool x,String m){if(!x)throw StateError(m);}
String sha(String p){final r=Process.runSync('/usr/bin/sha256sum',[p]);require(r.exitCode==0,'sha256sum failed: $p');return (r.stdout as String).split(RegExp(r'\s+')).first;}
Map<String,String> baseEnv(String variant)=>{'PATH':'$toolchain:/home/bsutton/.cargo/bin:/usr/bin:/bin','HOME':'/home/bsutton','CARGO_HOME':'/home/bsutton/.cargo','RUSTUP_HOME':'/home/bsutton/.rustup','TMPDIR':tmp,'CARGO_TARGET_DIR':'$root/$variant/build-target'};
String package(String v)=>'$root/$v/rust/revault_page_api';
String bin(String v)=>'$root/$v/build-target/release/examples/securevec_pressure_profile';
void save(String name,Object value)=>File('$raw/$name').writeAsStringSync(value is String?value:'${const JsonEncoder.withIndent('  ').convert(value)}\n',flush:true);
ProcessResult cmd(String key,List<String> argv,{required Map<String,String> env,int seconds=300,String? cwd}){final cmd=['/usr/bin/timeout','--kill-after=30s','${seconds}s',...argv];save('$key.command.json',{'argv':cmd,'cwd':cwd??repo,'env':env,'timeout_seconds':seconds});final sw=Stopwatch()..start();final r=Process.runSync(cmd.first,cmd.skip(1).toList(),workingDirectory:cwd,environment:env,includeParentEnvironment:false);sw.stop();File('$raw/$key.stdout.log').writeAsStringSync(r.stdout as String,flush:true);File('$raw/$key.stderr.log').writeAsStringSync(r.stderr as String,flush:true);save('$key.status.json',{'exit_code':r.exitCode,'elapsed_ms':sw.elapsedMilliseconds,'timed_out':r.exitCode==124||r.exitCode==137});return r;}
void copyTree(String from,String to){final r=Process.runSync('/bin/cp',['-a','$from/.',to]);require(r.exitCode==0,'cp failed $from -> $to');}
String manifest(String v){final d=Directory(package(v));final files=d.listSync(recursive:true,followLinks:false).whereType<File>().where((f)=>!f.path.contains('/build-target/')).toList()..sort((a,b)=>a.path.compareTo(b.path));final rows=<String>[];for(final f in files){rows.add('${sha(f.path)}  ${f.path.substring(root.length+1)}');}return '${rows.join('\n')}\n';}
void main(List<String> args){require(args.isEmpty,'runner takes no arguments');Directory(raw).createSync(recursive:true);require(!Directory(root).existsSync(),'isolated target already exists; refusing overwrite');Directory(root).createSync(recursive:true);final source='$rust/$crate';for(final v in ['old','new']){final pkg=package(v);Directory(pkg).createSync(recursive:true);copyTree(source,pkg);File('$root/$v/LICENSE').writeAsBytesSync(File('$repo/LICENSE').readAsBytesSync());File('$pkg/Cargo.lock').writeAsBytesSync(File('$rust/Cargo.lock').readAsBytesSync());var toml=File('$pkg/Cargo.toml').readAsStringSync();if(toml.contains('[workspace]')){toml=toml.replaceFirst('[workspace]','[workspace]\nresolver = "2"');}else{toml+='\n[workspace]\nresolver = "2"\n';}File('$pkg/Cargo.toml').writeAsStringSync(toml);Directory('$pkg/examples').createSync(recursive:true);File('$pkg/examples/securevec_pressure_profile.rs').writeAsStringSync(profileSource);}for(final rel in ['src/arena.rs','src/secure_heap.rs']){final dstOld=File('${package('old')}/$rel');final r=Process.runSync('/usr/bin/git',['show','HEAD:rust/$crate/$rel'],workingDirectory:repo);require(r.exitCode==0,'git show failed $rel');dstOld.writeAsStringSync(r.stdout as String);}
File('$raw/securevec_pressure_profile.rs.txt').writeAsStringSync(profileSource);save('base-and-source.json',{'head':Process.runSync('/usr/bin/git',['rev-parse','HEAD'],workingDirectory:repo).stdout.toString().trim(),'old_source':['src/arena.rs','src/secure_heap.rs'].map((p)=>sha('${package('old')}/$p')).toList(),'new_source':['src/arena.rs','src/secure_heap.rs'].map((p)=>sha('${package('new')}/$p')).toList(),'source_diff':Process.runSync('/usr/bin/git',['diff','--','rust/revault_page_api/src/arena.rs','rust/revault_page_api/src/secure_heap.rs'],workingDirectory:repo).stdout.toString(),'isolated_root':root});
for(final v in ['old','new']){final lock=cmd('$v-offline-lock-refresh',[cargo,'+1.88.0','tree','--manifest-path','${package(v)}/Cargo.toml','--offline','-e','normal'],env:baseEnv(v),seconds:90);require(lock.exitCode==0,'offline lock refresh failed for $v');final r=cmd('$v-dependency-tree',[cargo,'+1.88.0','tree','--manifest-path','${package(v)}/Cargo.toml','--locked','--offline','-e','normal'],env:baseEnv(v),seconds:90);require(r.exitCode==0,'dependency tree failed for $v');File('$raw/$v-dependency-tree.txt').writeAsStringSync(r.stdout as String,flush:true);final lockText=File('${package(v)}/Cargo.lock').readAsStringSync();for(final identity in {'getrandom':'0.4.3|300e883d756b2e4ec94e02791f39b04b522276138852cfc41d9fb7e904106099','zeroize':'1.9.0|e13c156562582aa81c60cb29407084cdb54c4164760106ab78e6c5b0858cf64e','libc':'0.2.189|3eaf3ede3fee6db1a4c2ee091bf8a8b4dccdc6d17f656fb07896ee72867612f2'}.entries){final block=lockText.split('[[package]]').firstWhere((b)=>b.contains('name = \"${identity.key}\"'),orElse:()=> '');require(block.contains('version = \"${identity.value.split('|').first}\"')&&block.contains('checksum = \"${identity.value.split('|').last}\"'),'${identity.key} lock identity mismatch in $v');}}final oldTree=File('$raw/old-dependency-tree.txt').readAsStringSync().replaceAll('$root/old/','<ISOLATED>/');final newTree=File('$raw/new-dependency-tree.txt').readAsStringSync().replaceAll('$root/new/','<ISOLATED>/');File('$raw/dependency-trees-normalized.txt').writeAsStringSync(oldTree,flush:true);require(oldTree==newTree,'old/new dependency trees differ after crate-root normalization');
for(final v in ['old','new']){final r=cmd('$v-build',[cargo,'+1.88.0','build','--manifest-path','${package(v)}/Cargo.toml','--locked','--offline','--release','--example','securevec_pressure_profile'],env:baseEnv(v),seconds:300);require(r.exitCode==0,'release build failed for $v');require(File(bin(v)).existsSync(),'missing $v binary');}
final page=Process.runSync('/usr/bin/getconf',['PAGESIZE']);require(page.exitCode==0&&page.stdout.toString().trim()=='4096','host page size not 4096');for(final v in ['old','new']){final r=cmd('$v-pressure',[bin(v),v],env:{...baseEnv(v),'PROFILE_HOST_PAGE_SIZE':'4096'},seconds:30);File('$raw/$v-pressure.jsonl').writeAsStringSync(r.stdout as String,flush:true);require(r.exitCode==0,'pressure profile failed for $v');final output=r.stdout as String;if(v=='old'){require(output.contains('"outcome":"expected_refusal_not_ignored"'),'old expected refusal absent');require(output.contains('"error":"WeakAllocationDisabled"'),'wrong old refusal');}else{require(output.contains('"outcome":"completed"')&&output.contains('"allocations":128'),'new profile did not complete exact 128 allocations');}}
for(final v in ['old','new']){File('$raw/$v-isolated-manifest.sha256').writeAsStringSync(manifest(v),flush:true);save('$v-binary.json',{'path':bin(v),'sha256':sha(bin(v))});}save('host-gates.json',{'getconf_pagesize':page.stdout.toString().trim(),'memlock_expected_bytes':8388608,'profile_cap_seconds':30,'build_cap_seconds':300,'workspace_resolver':'2','same_dependency_tree':true,'profile_count':'old natural refusal + new 128 allocations','hot_timing_launched':false});print(green('Approved pressure profile completed; no hot timing was run.'));
